for m in re.finditer(r'uni:(\w+) a uni:Course ;\s*uni:isTaughtIn uni:(\w+)', text):
    course_dept[m.group(1)] = m.group(2)

# parse students enrollments with single semicolon-separated predicates
# We'll use line-based parse for enrollment lines containing ':isEnrolledIn'
students = {}
current_student = None
for line in text.splitlines():
    if ' a uni:Person' in line and 'uni:Student' in line:
        mid = line.strip().split()[0]
        current_student = mid
        continue
    if current_student and 'isEnrolledIn' in line:
        # parse the subject and enrollments
        # line like "uni:Student1 uni:isEnrolledIn uni:CS101, uni:Bio101, ... ; uni:hasEnrollmentDate ..."
        subj = line.strip().split()[0]
        m = re.search(r'uni:isEnrolledIn\s+(.*?);', line)
        if not m:
            m = re.search(r'uni:isEnrolledIn\s+(.*)$', line)
        if m:
            courses = re.findall(r'uni:([\w]+)', m.group(1))
            students.setdefault(subj, {'courses': set(), 'enroll': None, 'grad': None})
            students[subj]['courses'].update(courses)
    if current_student and 'hasEnrollmentDate' in line:
        dm = re.search(r'uni:hasEnrollmentDate\s+"([\d-]+)"', line)
        if dm:
            students.setdefault(current_student, {'courses': set(), 'enroll': None, 'grad': None})
            students[current_student]['enroll'] = dm.group(1)
    if current_student and 'hasGraduationDate' in line:
        gm = re.search(r'uni:hasGraduationDate\s+"([\d-]+)"', line)
        if gm:
            students.setdefault(current_student, {'courses': set(), 'enroll': None, 'grad': None})
            students[current_student]['grad'] = gm.group(1)

# There may be multi-line records; let's print parsed student info
print('Course->dept:', course_dept)
ref = date(2025,8,16)
def current(s):
    if s['enroll'] is None: return False
    try:
        en = date.fromisoformat(s['enroll'])
    except: return False
    if en > ref: return False
    if s.get('grad'):
        try:
            gd = date.fromisoformat(s['grad'])
            if gd <= ref: return False
        except: pass
    return True

dept_students = {}
for sid, info in students.items():
    if not current(info): continue
    for c in info['courses']:
        if c in course_dept:
            d = course_dept[c]
            dept_students.setdefault(d, set()).add(sid)

for d, ss in dept_students.items():
    print(d, len(ss), sorted(ss))
